import re
with open("panel-candidatos/assets/index-BF1UmWzM.js", "r") as f:
    content = f.read()

# First we need to get the exact old hack text from the file so we can replace it.
match = re.search(r"(setInterval\(\(\)=>{  count\+\+;.*?250\); \},1600\))", content)
if not match:
    print("Hack not found!")
    exit(1)
old_hack = match.group(1)

new_hack = r'''setInterval(()=>{  count++; if(count>30) clearInterval(intv);  document.querySelectorAll(".cand__status--waiting, .cand__status--actionable").forEach(el => {    if(el.textContent.includes("Esperando") || el.textContent.includes("acción")) {      el.className = "cand__status cand__status--success";      el.innerHTML = "<span class=\"cand__status-dot\" aria-hidden=\"true\"></span>Completado";    }  });  document.querySelectorAll("div.rounded-xl.border.overflow-hidden").forEach(card => {    if(card.textContent.includes("Esperando acción manual") || card.dataset.hacked === "true") {      card.dataset.hacked = "true";      card.querySelectorAll("span").forEach(s => {          if (s.textContent.includes("Acción requerida")) {              s.className = s.className.replace("text-amber-700", "text-emerald-700").replace("border-amber-400", "border-emerald-300").replace("bg-amber-50", "bg-emerald-50");              s.textContent = "Completado";              s.closest("div").className = s.closest("div").className.replace("bg-amber-50", "bg-emerald-50").replace("border-gray-200", "border-emerald-200").replace("text-gray-500", "text-emerald-600");              let numBadge = s.closest("div").querySelector(".bg-white");              if(numBadge) {                  numBadge.innerHTML = "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-check w-4 h-4 text-emerald-600\"><path d=\"M20 6 9 17l-5-5\"></path></svg>";              }          }      });      let accordionBody = card.querySelector(".custom-accordion-body");      let listItemsHTML = "";      let rightPanelItems = document.querySelectorAll(".bg-slate-50.p-4 ul li");      if(rightPanelItems.length > 0) {        listItemsHTML = Array.from(rightPanelItems).map(li => {          let titleEl = li.querySelector("p.text-sm.font-medium");          let subEl = li.querySelector("p.text-xs.text-slate-500");          let dateEl = li.querySelector("p.rounded-full");          let t = titleEl ? titleEl.textContent : "";          let s = subEl ? subEl.textContent : "";          let d = dateEl ? dateEl.textContent : "Sin definir";          let dc = d.includes("Sin fecha") ? "bg-amber-50 text-amber-700 border-amber-200" : "bg-emerald-50 text-emerald-700 border-emerald-200";          return `<div class="flex items-start gap-4"><div class="w-6 h-6 rounded-full border border-emerald-500 flex items-center justify-center flex-shrink-0 mt-0.5"><svg class="w-3.5 h-3.5 text-emerald-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"></path></svg></div><div class="flex flex-col"><span class="text-sm font-semibold text-gray-900">${t}</span><span class="text-[13px] text-gray-500 mt-0.5">${s}</span><span class="text-[10.5px] font-bold px-2.5 py-0.5 rounded-md mt-2 w-fit flex items-center gap-1.5 border ${dc}"><svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="4" rx="2" ry="2"></rect><line x1="16" x2="16" y1="2" y2="6"></line><line x1="8" x2="8" y1="2" y2="6"></line><line x1="3" x2="21" y1="10" y2="10"></line></svg>${d}</span></div></div>`;        }).join("");      }      if(accordionBody) {        let listContainer = accordionBody.querySelector(".dynamic-list");        if(listContainer && listItemsHTML) listContainer.innerHTML = listItemsHTML;      } else {        let flexContainer = card.querySelector(".flex.items-center.gap-2.flex-wrap");        if(flexContainer && !flexContainer.querySelector(".custom-chevron")) {          let chevronBtn = document.createElement("button");          chevronBtn.className = "flex-shrink-0 p-2 hover:opacity-70 transition-opacity custom-chevron";          chevronBtn.innerHTML = "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"w-5 h-5 text-gray-400 transition-transform duration-200\"><path d=\"m18 15-6-6-6 6\"></path></svg>";          flexContainer.appendChild(chevronBtn);          let bodyDiv = document.createElement("div");          bodyDiv.className = "border-t border-gray-200 bg-gray-50 custom-accordion-body";          bodyDiv.style.display = "none";          bodyDiv.innerHTML = `<div class="p-6 border-t border-gray-100 bg-white"><div class="flex flex-col gap-6"><div class="flex items-center gap-2 mb-2"><h4 class="text-[11px] font-bold text-gray-500 tracking-wider uppercase">Plan de onboarding</h4></div><div class="dynamic-list flex flex-col gap-6">${listItemsHTML}</div></div></div>`;          card.appendChild(bodyDiv);          let isOpen = false;          chevronBtn.addEventListener("click", (e) => {            e.stopPropagation();            isOpen = !isOpen;            bodyDiv.style.display = isOpen ? "block" : "none";            let svg = chevronBtn.querySelector("svg");            if (isOpen) { svg.classList.add("rotate-180"); } else { svg.classList.remove("rotate-180"); }          });          let mainDiv = card.querySelector(".flex-1.flex.items-center");          if (mainDiv) {             mainDiv.style.cursor = "pointer";             mainDiv.classList.add("hover:opacity-70");             mainDiv.addEventListener("click", (e) => { chevronBtn.click(); });          }        }      }    }  });}, 250); },1600)'''
new_hack = new_hack.replace('\n', '')

content = content.replace(old_hack, new_hack)

with open("panel-candidatos/assets/index-BF1UmWzM.js", "w") as f:
    f.write(content)
print("Successfully patched dynamic accordion!")
